import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Langues des widgets, sources HA et Climate","description":"DE/EN/FR, attributs, unités et commandes climatiques facultatives depuis Studio 0.1.296.","frontmatter":{"title":"Langues des widgets, sources HA et Climate","description":"DE/EN/FR, attributs, unités et commandes climatiques facultatives depuis Studio 0.1.296."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/ha-quellen-climate.md","filePath":"fr/projects/grafik-visual-studio/ha-quellen-climate.md","lastUpdated":1793128957000}'),n={name:"fr/projects/grafik-visual-studio/ha-quellen-climate.md"};function r(o,e,u,l,c,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="langues-des-widgets-sources-ha-et-climate" tabindex="-1">Langues des widgets, sources HA et Climate <a class="header-anchor" href="#langues-des-widgets-sources-ha-et-climate" aria-label="Permalink to &quot;Langues des widgets, sources HA et Climate&quot;">​</a></h1><p>Depuis <strong>Studio 0.1.296</strong>, les <strong>62 types restants</strong> (Spécial, jauges, flux de données et sept paquets inclus) proposent leurs propriétés et messages d’exécution en <strong>DE/EN/FR</strong>. L’interface générale du Studio reste DE/EN. <a href="/projects/grafik-visual-studio/ha-quellen-climate">Deutsch</a> · <a href="/en/projects/grafik-visual-studio/ha-quellen-climate">English</a>.</p><h2 id="choisir-une-langue" tabindex="-1">Choisir une langue <a class="header-anchor" href="#choisir-une-langue" aria-label="Permalink to &quot;Choisir une langue&quot;">​</a></h2><p><strong>Widget-Sprache</strong> dans les paramètres du projet définit la langue par défaut. Le groupe <strong>Langue du widget</strong> peut la remplacer. Calendar+, Energy, Industrial, Printer, Solar, Technic et Weather/Heating fonctionnent avec les versions de paquet existantes. Les textes personnels, identifiants d’entité et clés enregistrées restent inchangés.</p><h2 id="verifier-une-source-ha" tabindex="-1">Vérifier une source HA <a class="header-anchor" href="#verifier-une-source-ha" aria-label="Permalink to &quot;Vérifier une source HA&quot;">​</a></h2><p>Les sources liées en lecture proposent le groupe <strong>Sources et unités HA</strong>, initialement désactivé. Un attribut vide lit l’état ; sinon saisissez un attribut. <strong>Vérifier la source</strong> actualise la valeur, découvre les noms d’attribut et signale unité, données manquantes ou conversion incompatible. Les données structurées reçoivent une indication JSON. L’attribut doit correspondre au schéma attendu par le widget.</p><p>La conversion est facultative. Pour une source Energy, elle remplace l’ancien facteur sans le supprimer. Les affichages/calculs fixes suivent leur unité : Solar W/°C/%, énergie de batterie kWh, unité de température native Climate. Leur champ d’unité cible est verrouillé. Les sources configurables acceptent des unités compatibles de puissance, énergie, température, prix, longueur, volume, vitesse et pression. Sans métadonnées ou avec des unités incompatibles, la valeur est inconnue. Les cibles d’écriture HA restent natives.</p><p>Energy peut lire des attributs numériques Recorder ; un attribut manquant crée un espace dans l’historique. Des attributs historiques différents d’une même entité nécessitent des widgets de suivi séparés. La conversion C/F avec décalage ne s’applique pas à l’historique Energy. L’historique distinct du thermostat conserve ses sources HA natives ; les options de source concernent son affichage actuel. Recorder ne remplace pas entièrement le tableau de bord Énergie et les statistiques à long terme.</p><h2 id="commandes-climatiques" tabindex="-1">Commandes climatiques <a class="header-anchor" href="#commandes-climatiques" aria-label="Permalink to &quot;Commandes climatiques&quot;">​</a></h2><p>Activez <strong>Commandes climatiques</strong> sur <strong>Technic Thermostat – Temperature</strong>, puis choisissez les options nécessaires :</p><ul><li>Plage chauffage/refroidissement avec deux consignes et application commune.</li><li>Mode de fonctionnement et préréglage.</li><li>Ventilateur, oscillation verticale et horizontale.</li><li>Humidité cible et marche/arrêt.</li></ul><p>L’exécution propose uniquement les fonctions/valeurs annoncées par l’appareil. Limites et pas sont revérifiés côté serveur. La consigne unique existante reste disponible ; les appareils à deux consignes utilisent les commandes de plage. L’éditeur, la lecture seule et les états indisponibles désactivent les commandes. Agrandissez les widgets avec de nombreuses options ; la zone supplémentaire défile dans les petits widgets.</p><p>Les nouveaux groupes sont initialement désactivés. Projets, groupes et facteurs existants restent valides. Un service réussi confirme la transmission à HA, pas l’état physique de l’appareil. Appareils réels, Ingress/Companion, intégration de pages externes et réception des notifications nécessitent des tests sur l’installation.</p><p><a href="https://www.home-assistant.io/integrations/climate/" target="_blank" rel="noreferrer">HA Climate</a> · <a href="https://developers.home-assistant.io/docs/core/entity/climate/" target="_blank" rel="noreferrer">Fonctions des appareils</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Rapport de revue</a></p>',14)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
